body.script:
//
					const cfg      = document.getElementById('cfg').dataset;
					const ASSET    = cfg.asset;
					const REFRESH  = parseInt(cfg.refresh, 10) * 1000;
					let   INTERVAL = '4h';
					const klineUrl = (iv, limit) => '/api/klines/' + ASSET + '?interval=' + iv + '&limit=' + limit;
					const LIVE_BAND_URL = '/api/live-band/' + ASSET;
					const BANDS_URL = '/api/bands/' + ASSET;

					// Same browser-local-timezone shift every other TV chart page
					// in this addon applies — Lightweight Charts always renders
					// epoch seconds as UTC wall-clock time, so every timestamp fed
					// into the chart is pre-shifted by the viewer's own current
					// UTC offset first.
					const tzOffset = (() => {
						let zone;
						try {
							zone = Intl.DateTimeFormat().resolvedOptions().timeZone;
						} catch (e) {
							return 0;
						}
						const d = new Date();
						const utc = new Date(d.toLocaleString('en-US', { timeZone: 'UTC' }));
						const local = new Date(d.toLocaleString('en-US', { timeZone: zone }));
						return (local - utc) / 1000;
					})();

					const THEME_STORAGE_KEY = 'dankbit_theme';
					let DARK_MODE = localStorage.getItem(THEME_STORAGE_KEY) === 'dark';
					function rulerColor() { return DARK_MODE ? '#aaaaaa' : '#555555'; }
					document.getElementById('theme-select').value = DARK_MODE ? 'dark' : 'light';
					document.body.classList.toggle('dark', DARK_MODE);

					const chart = LightweightCharts.createChart(document.getElementById('chart-container'), {
						width: window.innerWidth, height: window.innerHeight,
						layout: {
							background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
							textColor: DARK_MODE ? '#d1d4dc' : '#333333',
						},
						grid: { vertLines: { visible: false }, horzLines: { visible: false } },
						crosshair: { mode: LightweightCharts.CrosshairMode.Normal, horzLine: { labelBackgroundColor: 'blue' } },
						rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc', timeVisible: true, secondsVisible: false },
						localization: {
							timeFormatter: ts => new Date(ts * 1000).toLocaleString('de-DE', {
								timeZone: 'UTC',
								month: 'short', day: 'numeric',
								hour: '2-digit', minute: '2-digit',
							}),
						},
					});

					window.addEventListener('resize', () => {
						chart.resize(window.innerWidth, window.innerHeight);
					});

					const series = chart.addCandlestickSeries({
						upColor: '#26a69a', downColor: '#ef5350',
						borderVisible: false, wickUpColor: '#26a69a', wickDownColor: '#ef5350',
					});

					// The indicators on this page: one point per persisted
					// dankbit.live.band row (a genuine append-only hourly log, one
					// new row per cron tick — not a continuously-refined bucket
					// like every other snapshot model in this addon). Colors
					// match the same fields' lines on the Delta Chart's own
					// "Bands" checkbox, for at-a-glance consistency even though
					// these are fully separate, isolated series/data.
					const highResistanceSeries = chart.addLineSeries({
						color: '#2e7d32', lineWidth: 2,
						lastValueVisible: true, priceLineVisible: false,
					});
					const lowSupportSeries = chart.addLineSeries({
						color: '#c62828', lineWidth: 2,
						lastValueVisible: true, priceLineVisible: false,
					});
					const gammaBandSeries = chart.addLineSeries({
						color: '#c9a0dc', lineWidth: 2, lineStyle: LightweightCharts.LineStyle.Dashed,
						lastValueVisible: true, priceLineVisible: false,
					});
					// Smart Liq Upper/Lower are deliberately NOT connected into a
					// line (lineVisible: false) — each row only ever contributes
					// a point to WHICHEVER of these two series is the stronger
					// side that row (see refreshLiveBand()'s dominance split), so
					// consecutive points across rows can flip sides entirely;
					// drawing a line through them would visually connect
					// unrelated upper/lower readings. The point itself is drawn
					// via setMarkers() instead.
					const smartLiqUpperSeries = chart.addLineSeries({
						color: '#2e7d32', lineWidth: 2, lineVisible: false,
						lastValueVisible: true, priceLineVisible: false,
					});
					const smartLiqLowerSeries = chart.addLineSeries({
						color: '#c62828', lineWidth: 2, lineVisible: false,
						lastValueVisible: true, priceLineVisible: false,
					});
					// Smart Liq Upper/Lower Avg — average of that side's raw
					// smart-liq level and its corresponding High/Resistance
					// (upper) or Low/Support (lower) point, one per row,
					// connected as a normal trend line (unlike the raw points
					// above, this isn't a "which side won" split — both sides
					// are computed and plotted every row they're available).
					const smartLiqUpperAvgSeries = chart.addLineSeries({
						color: '#00897b', lineWidth: 2,
						lastValueVisible: true, priceLineVisible: false,
					});
					const smartLiqLowerAvgSeries = chart.addLineSeries({
						color: '#d84315', lineWidth: 2,
						lastValueVisible: true, priceLineVisible: false,
					});

					// Smart Liq Upper/Lower (Expiry) — the same term-structure
					// indicator the Delta Chart's "Bands" checkbox draws: one
					// point per dankbit.bands instrument-row (nearest expiry
					// plus the tracked expiries after it — see
					// TRACKED_EXPIRY_COUNT), positioned at that instrument's own
					// expiration time rather than a poll timestamp, connected
					// point-to-point as a real term structure — unlike every
					// other indicator on this page, which is keyed to
					// dankbit.live.band's hourly poll history instead. Sourced
					// from /api/bands/<asset>, the same endpoint/data the Delta
					// Chart's Bands checkbox reads.
					const smartLiqUpperTermSeries = chart.addLineSeries({
						color: '#4fc3f7', lineWidth: 2, lineStyle: LightweightCharts.LineStyle.Dotted,
						lastValueVisible: true, priceLineVisible: false,
					});
					const smartLiqLowerTermSeries = chart.addLineSeries({
						color: '#fb8c00', lineWidth: 2, lineStyle: LightweightCharts.LineStyle.Dotted,
						lastValueVisible: true, priceLineVisible: false,
					});

					// Invisible series reserving future logical bars on the shared
					// time axis, same technique the Delta/Gamma Chart's own
					// futureAxisSeries uses — without it, Lightweight Charts has no
					// established bar spacing past the last real candle, and the
					// far-future Smart Liq (Expiry) points above would map onto
					// that region inconsistently between timeframes (this was the
					// actual cause of those points appearing "misaligned"/at the
					// wrong spot when switching timeframe: 1h vs 4h vs 1d each
					// imply a different real time-per-bar, so the axis needs
					// interval-matched future bars reserved explicitly, not left
					// for the library to improvise). Unlike the Delta/Gamma Chart's
					// fixed FUTURE_MARGIN_DAYS, this page sizes the reservation
					// dynamically off the furthest future Smart Liq (Expiry) point
					// actually fetched (see rebuildFutureAxis()/refreshBandsTerm()),
					// since tracked expiries can sit anywhere from days to a month
					// out — a fixed margin could silently fall short.
					const futureAxisSeries = chart.addLineSeries({
						color: 'rgba(0,0,0,0)', lineWidth: 1,
						lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});
					let futureTickCount = 0;

					function setStatus(text) { document.getElementById('status').textContent = text; }

					function toCandle(k) {
						return { time: Math.floor(k.t / 1000) + tzOffset, open: parseFloat(k.o), high: parseFloat(k.h), low: parseFloat(k.l), close: parseFloat(k.c) };
					}

					const TF_WINDOW = { '1h': 30, '4h': 15, '1d': 365 };
					const BARS_PER_DAY = { '1h': 24, '4h': 6, '1d': 1 };
					// Live Band data arrives hourly; when the chart is switched
					// to a wider timeframe, every hourly reading that falls
					// within one of that timeframe's own candles should be
					// grouped into that candle rather than still plotted at its
					// own separate hour mark (see bucketTime()/refreshLiveBand()).
					const BUCKET_SECONDS = { '1h': 3600, '4h': 4 * 3600, '1d': 86400 };

					let realCandles = [];

					function applyVisibleRange() {
						const days = TF_WINDOW[INTERVAL] || 21;
						const barsPerDay = BARS_PER_DAY[INTERVAL] || 24;
						const lastIndex = realCandles.length + futureTickCount - 1;
						chart.timeScale().setVisibleLogicalRange({
							from: lastIndex - days * barsPerDay,
							to:   lastIndex,
						});
					}

					// Rebuilds futureAxisSeries so the shared time axis has real,
					// interval-matched logical bars reserved out to at least
					// `maxFutureTimeSec` (a tzOffset-shifted epoch second, same
					// format as every other series' own time values on this page) —
					// called from refreshBandsTerm() with the furthest Smart Liq
					// (Expiry) point actually fetched, so the reservation always
					// covers whatever's currently tracked regardless of how far out
					// it is. A few bars of extra margin are added past that point
					// so it doesn't sit flush against the chart's right edge.
					function rebuildFutureAxis(maxFutureTimeSec) {
						const intervalSec = BUCKET_SECONDS[INTERVAL] || 3600;
						const lastClose = realCandles.length ? realCandles[realCandles.length - 1].close : 0;
						const lastTime = realCandles.length
							? realCandles[realCandles.length - 1].time
							: (Math.floor(Date.now() / 1000) + tzOffset);
						const count = maxFutureTimeSec > lastTime
							? Math.ceil((maxFutureTimeSec - lastTime) / intervalSec) + 3
							: 0;
						const futureTicks = [];
						for (let i = 1; i <= count; i++) {
							futureTicks.push({ time: lastTime + i * intervalSec, value: lastClose });
						}
						futureTickCount = futureTicks.length;
						futureAxisSeries.setData(futureTicks);
						applyVisibleRange();
					}

					async function loadCandles() {
						const resp = await (await fetch(klineUrl(INTERVAL, 500))).json();
						const klines = (resp.result || []).slice().reverse();
						realCandles = klines.map(toCandle);
						series.setData(realCandles);
						applyVisibleRange();
					}

					async function updateLatestCandle() {
						const resp = await (await fetch(klineUrl(INTERVAL, 2))).json();
						const klines = resp.result || [];
						if (!klines.length) return;
						const updated = toCandle(klines[0]);
						if (realCandles.length && realCandles[realCandles.length - 1].time === updated.time) {
							realCandles[realCandles.length - 1] = updated;
						} else {
							realCandles.push(updated);
						}
						series.setData(realCandles);
					}

					async function setTf(iv) {
						INTERVAL = iv;
						await loadCandles();
						await refreshLiveBand();
						await refreshBandsTerm();
					}

					// Live Band rows are computed hourly, but points must land
					// on whatever candle width is currently selected — on 1h
					// this just floors to the top of the hour (dropping the
					// minute/second the cron happened to fire at); switched to
					// 4h, every hourly reading landing before the next 4h candle
					// collapses into the current one instead of still showing
					// as 4 separate points spread across it, same idea one more
					// level up for 1d. Uses the same epoch-aligned bucket
					// boundaries (multiples of BUCKET_SECONDS[INTERVAL] since
					// 1970-01-01 00:00 UTC) real candles/klines already sit on.
					function bucketTime(epochMs) {
						// Floor to the bucket boundary in real (UTC) time FIRST,
						// then apply the display shift — not the other way
						// around. Real candles' own time is
						// floor(utcOpenTime) + tzOffset, where utcOpenTime is
						// already a UTC-aligned multiple of the bucket width;
						// flooring only after adding tzOffset would instead
						// align to a grid offset by tzOffset mod bucket, which
						// only coincides with the real candles' own boundaries
						// when tzOffset happens to be an exact multiple of the
						// bucket width — true for most timezones at 1h, but
						// essentially never at 4h (e.g. +3:30, +5:30, and most
						// whole-hour offsets that aren't 0/4/8/... all miss).
						const rawSeconds = Math.floor(epochMs / 1000);
						const bucket = BUCKET_SECONDS[INTERVAL] || 3600;
						return Math.floor(rawSeconds / bucket) * bucket + tzOffset;
					}

					// Read-only — this page never creates dankbit.live.band rows
					// itself (unlike /x/'s or /y/'s own live-refine pattern); only
					// that model's hourly cron does, so this just displays
					// whatever has accumulated so far.
					async function refreshLiveBand() {
						const data = await (await fetch(LIVE_BAND_URL)).json();
						const rawPoints = data.points || [];
						// Collapse to (at most) one point per bucket of the
						// CURRENT timeframe — e.g. on 4h, every hourly reading
						// landing before the next 4h candle collapses into the
						// current one; if more than one row lands in the same
						// bucket, the later one wins, same "most recent value"
						// precedence as everywhere else in this addon;
						// Lightweight Charts also requires strictly increasing,
						// unique times per series.
						const byBucket = new Map();
						rawPoints.forEach(p => byBucket.set(bucketTime(p.t), p));
						const points = Array.from(byBucket.keys())
							.sort((a, b) => a - b)
							.map(time => Object.assign({ time }, byBucket.get(time)));

						highResistanceSeries.setData(points.map(p => ({
							time: p.time,
							value: p.high_resistance,
						})));
						lowSupportSeries.setData(points.map(p => ({
							time: p.time,
							value: p.low_support,
						})));
						gammaBandSeries.setData(points.map(p => ({
							time: p.time,
							value: p.gamma_band,
						})));
						smartLiqUpperAvgSeries.setData(
							points.filter(p => p.smart_liq_upper_avg).map(p => ({
								time: p.time,
								value: p.smart_liq_upper_avg,
							}))
						);
						smartLiqLowerAvgSeries.setData(
							points.filter(p => p.smart_liq_lower_avg).map(p => ({
								time: p.time,
								value: p.smart_liq_lower_avg,
							}))
						);
						// Per row, plot only the raw smart-liq point of
						// WHICHEVER side is stronger that row — compared via
						// smart_liq_upper_strength/smart_liq_lower_strength (NOT
						// the raw upper/lower prices: upper is, by construction,
						// always a higher PRICE than lower since it's anchored
						// to the top of the band, so comparing prices would
						// always pick "upper" and never reflect actual
						// dominance). Each series only ever receives the rows
						// where IT won, with lineVisible:false (see series
						// creation above) so consecutive winning points are
						// never connected into a line — setMarkers() alone
						// draws each one as a standalone dot. A lone value (the
						// other side absent that row) counts as dominant by
						// default.
						const upperDominant = [];
						const lowerDominant = [];
						points.forEach(p => {
							const hasUpper = !!p.smart_liq_upper;
							const hasLower = !!p.smart_liq_lower;
							if (!hasUpper && !hasLower) return;
							let upperWins = false, lowerWins = false;
							if (hasUpper && hasLower) {
								if (p.smart_liq_upper_strength > p.smart_liq_lower_strength) upperWins = true;
								else if (p.smart_liq_lower_strength > p.smart_liq_upper_strength) lowerWins = true;
							} else if (hasUpper) {
								upperWins = true;
							} else {
								lowerWins = true;
							}
							if (upperWins) upperDominant.push({ time: p.time, value: p.smart_liq_upper });
							if (lowerWins) lowerDominant.push({ time: p.time, value: p.smart_liq_lower });
						});
						smartLiqUpperSeries.setData(upperDominant);
						smartLiqLowerSeries.setData(lowerDominant);
						smartLiqUpperSeries.setMarkers(
							upperDominant.map(p => ({ time: p.time, position: 'inBar', color: '#2e7d32', shape: 'circle', size: 1 }))
						);
						smartLiqLowerSeries.setMarkers(
							lowerDominant.map(p => ({ time: p.time, position: 'inBar', color: '#c62828', shape: 'circle', size: 1 }))
						);
					}

					// Term-structure Smart Liquidity — ported from the Delta
					// Chart's own "Bands" checkbox (refreshBands() in
					// dankbit_templates.xml): one point per dankbit.bands
					// instrument-row, at that instrument's own expiration time,
					// connected across the nearest expiry and the tracked
					// expiries after it. Read-only, same as refreshLiveBand()
					// above — /api/bands/<asset> never triggers a new
					// computation, only dankbit.bands' own hourly
					// compute_snapshot() cron does.
					async function refreshBandsTerm() {
						const data = await (await fetch(BANDS_URL)).json();
						// Unlike the Delta Chart's own Bands checkbox (which shows
						// the full historical term structure, including already-
						// expired instruments' frozen rows), this page only ever
						// plots FUTURE points — r.t is that instrument's own real
						// expiration time (ms), compared against the real,
						// un-tz-shifted current time.
						const now = Date.now();
						const rows = (data.bands || []).filter(r => r.t >= now);
						// 0.0 means absent (see dankbit.bands' smart_liq_upper_price/
						// smart_liq_lower_price) — filtered out rather than plotted,
						// same principle refreshLiveBand() above applies.
						const upperRows = rows.filter(r => r.smart_liq_upper_price);
						const lowerRows = rows.filter(r => r.smart_liq_lower_price);
						smartLiqUpperTermSeries.setData(upperRows.map(r => ({
							time: Math.floor(r.t / 1000) + tzOffset,
							value: r.smart_liq_upper_price,
						})));
						smartLiqLowerTermSeries.setData(lowerRows.map(r => ({
							time: Math.floor(r.t / 1000) + tzOffset,
							value: r.smart_liq_lower_price,
						})));
						// Per-point dominance emphasis, same convention as the
						// Delta Chart: each row compared only against its own
						// counterpart at that same expiry, not some single
						// reference row.
						smartLiqUpperTermSeries.setMarkers(upperRows.map(r => ({
							time: Math.floor(r.t / 1000) + tzOffset,
							position: 'inBar', color: '#4fc3f7', shape: 'circle',
							size: r.smart_liq_upper_strength > r.smart_liq_lower_strength ? 1 : 0,
						})));
						smartLiqLowerTermSeries.setMarkers(lowerRows.map(r => ({
							time: Math.floor(r.t / 1000) + tzOffset,
							position: 'inBar', color: '#fb8c00', shape: 'circle',
							size: r.smart_liq_lower_strength > r.smart_liq_upper_strength ? 1 : 0,
						})));
						// Reserve real, interval-matched future bars out to the
						// furthest point just plotted (or none, if nothing's
						// tracked right now) — see rebuildFutureAxis().
						const futureTimes = rows.map(r => Math.floor(r.t / 1000) + tzOffset);
						rebuildFutureAxis(futureTimes.length ? Math.max(...futureTimes) : 0);
					}

					function applyTheme() {
						document.body.classList.toggle('dark', DARK_MODE);
						chart.applyOptions({
							layout: {
								background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
								textColor: DARK_MODE ? '#d1d4dc' : '#333333',
							},
							rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
							timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						});
					}

					function onThemeChange() {
						DARK_MODE = document.getElementById('theme-select').value === 'dark';
						localStorage.setItem(THEME_STORAGE_KEY, DARK_MODE ? 'dark' : 'light');
						applyTheme();
					}

					let rulerActive = false;
					let rulerPrice1 = null;
					let rulerLines  = [];

					function toggleRuler() {
						rulerActive = !rulerActive;
						document.getElementById('ruler-btn').classList.toggle('active', rulerActive);
						rulerLines.forEach(l => series.removePriceLine(l));
						rulerLines = [];
						rulerPrice1 = null;
						const info = document.getElementById('ruler-info');
						info.style.display = 'none';
						info.textContent = '';
					}

					chart.subscribeClick(param => {
						if (!rulerActive || !param.point) return;
						const price = series.coordinateToPrice(param.point.y);
						if (rulerPrice1 === null) {
							rulerPrice1 = price;
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: DARK_MODE ? '#e8e8e8' : '#000000', title: '①',
							}));
						} else {
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: DARK_MODE ? '#e8e8e8' : '#000000', title: '②',
							}));
							const pct = ((price - rulerPrice1) / rulerPrice1 * 100);
							const sign = pct >= 0 ? '+' : '';
							const info = document.getElementById('ruler-info');
							info.style.display = 'block';
							info.textContent = rulerPrice1.toFixed(0) + ' → ' + price.toFixed(0) + '   ' + sign + pct.toFixed(2) + '%';
							rulerPrice1 = null;
						}
					});

					async function init() {
						try {
							await loadCandles();
							await refreshLiveBand();
							await refreshBandsTerm();
							setStatus(ASSET + ' · Live Band (hourly, nearest expiry)');
						}
						catch (e) { setStatus('Error: ' + e.message); }
					}
					init();
					setInterval(updateLatestCandle, 5000);
					setInterval(refreshLiveBand, REFRESH);
					setInterval(refreshBandsTerm, REFRESH);
				//
